package com.inridemart.payment;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Configuration class SecurityConfig { @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(AbstractHttpConfigurer::disable).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/v3/api-docs/**","/swagger-ui.html","/swagger-ui/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} @Bean JwtFilter jwtFilter(@Value("${security.jwt.secret}")String s,@Value("${security.jwt.issuer}")String i){return new JwtFilter(s,i);} static class JwtFilter extends OncePerRequestFilter {final SecretKey key;final String issuer;JwtFilter(String s,String i){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));issuer=i;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse q,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims x=Jwts.parser().verifyWith(key).requireIssuer(issuer).build().parseSignedClaims(h.substring(7)).getPayload();if("access".equals(x.get("token_use",String.class)))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(UUID.fromString(x.getSubject()),null,List.of(new SimpleGrantedAuthority("ROLE_"+x.get("role",String.class)))));}catch(RuntimeException ignored){SecurityContextHolder.clearContext();}c.doFilter(r,q);} } }
